#!/usr/bin/env python3
"""rc.1 fix pass, ratings (D-DATA; ADR-0032). Idempotent: a second run changes nothing.

  M4  Repeated passes of one model with one prompt family are ONE rater (DATA_FIX_BRIEF §3): every raterType llm
      rating gets raterId emstagent:llm-rater@<model>/<prompt family>, passIndex (1-3) and sessionId (the batch the
      pass came from), its provenance.agent names that one rater, and its method ends with the caveat
      "run-to-run consistency of one model; not independent raters; not reliability".
  M2  validationStatus on every rating (draft: nothing is reviewed). The v1-analyst batches are regenerated by
      scripts/migrate_v1.py 1.1.0 (evidence label S, provenance llm-assisted); this script only checks them.
  M8  sampleFrame on the emst-exposure@2.0 batch: the 57 tasks were chosen because WP-08 flagged them as changing.

Run: python3 -I docs/build/rc1-fix/fix_ratings.py   Licence: Apache-2.0.
"""
from __future__ import annotations

import re
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
import rc1lib as R  # noqa: E402

L = R.L
A = L.DATA_V2 / "assessments"
CAVEAT = "run-to-run consistency of one model; not independent raters; not reliability"
SAMPLE_FRAME_X = ("WP-08 change atoms (selected on outcome): the 57 tasks were chosen because WP-08 had already "
                  "flagged them as changing, so the batch supports no distributional statement (ADR-0032; review M8)")
FAMILY_RE = re.compile(r"([A-Za-z0-9][A-Za-z0-9._-]*@\d+)$")


def prompt_family(pv: str) -> str:
    """'docs/build/S2-closeout-A/rating/pass2.txt@s2a-craft@1' -> 's2a-craft@1' (a pass-specific prompt file before
    the family); 'wp06-craft-blind@1' -> itself."""
    pv = pv.strip()
    fam = pv.split("@", 1)[1] if pv.count("@") >= 2 else pv
    if not FAMILY_RE.fullmatch(fam):
        raise SystemExit(f"no prompt family in promptVersion {pv!r}")
    return fam


def rater_id(model: str, family: str) -> str:
    return f"emstagent:llm-rater@{model}/{family}"


def with_validation_status(rec: dict) -> dict:
    if rec.get("validationStatus"):
        return rec
    return R.insert_after(rec, "status", "validationStatus", "draft")


def fix_llm(rec: dict, stem: str) -> dict:
    prov = dict(rec["provenance"])
    model, pv = prov.get("toolVersion"), prov.get("promptVersion")
    rid = rater_id(model, prompt_family(pv))
    m = re.search(r"pass(\d)$", stem)
    if not m:
        raise SystemExit(f"{stem}: no pass number in the batch name")
    out = with_validation_status(rec)
    out["raterId"] = rid
    out = R.insert_after(out, "raterId", "passIndex", int(m.group(1)))
    out = R.insert_after(out, "passIndex", "sessionId", stem)
    meth = out["method"].rstrip()
    if CAVEAT not in meth:
        out["method"] = meth.rstrip(".") + "; " + CAVEAT
    prov["agent"] = [rid]
    out["provenance"] = prov
    if out.get("instrument") == "emst-exposure@2.0" and not out.get("sampleFrame"):
        out = R.insert_after(out, "codebookVersion", "sampleFrame", SAMPLE_FRAME_X)
    return out


def main():
    n_llm = n_other = 0
    for path in sorted(A.rglob("*.jsonl")):
        stem = path.stem

        def fn(rec, stem=stem):
            nonlocal n_llm, n_other
            if rec.get("type") not in L.RATING_TYPES:
                return None
            if rec.get("raterType") == "llm":
                new = fix_llm(rec, stem)
                n_llm += new != rec
                return new
            new = with_validation_status(rec)
            n_other += new != rec
            return new
        R.edit_jsonl(path, fn)
    # v1-analyst batches come from migrate_v1.py 1.1.0: check, never edit (they are generated files)
    bad = []
    for loc, rec in R.records(L.RATING_TYPES):
        if rec.get("raterType") == "v1-analyst":
            p = rec.get("provenance") or {}
            if rec.get("evidenceLabel") != "S" or p.get("method") != "llm-assisted" or rec.get("deploymentMode"):
                bad.append(rec.get("id"))
    if bad:
        raise SystemExit(f"{len(bad)} v1-analyst ratings still carry the old labels: run python3 scripts/migrate_v1.py first")
    R.summary(f"fix_ratings: {n_llm} llm and {n_other} other ratings changed")


if __name__ == "__main__":
    main()
